    runId: rc.runId,
    metricsSchemaVersion: 2,
    version: VERSION,
    releaseChannel: rc.config?.telemetryChannel ?? loadConfig().telemetryChannel,
    providerRoutes: providerRoutesWithQuality(rc),
    profile: rc.profile,
    mode: rc.mode,
