// src/ui/open-loops-overlay.ts
async function showOpenLoopsUI(ctx, sourceLoops, initialOverrides = []) {
  let overrides = [...initialOverrides];
  let changed = false;
  while (true) {
    const loops = applyLoopOverrides(sourceLoops, overrides);
    const labels = loops.map((loop, index) => index + 1 + ". [" + loop.status + "/" + loop.priority + "] " + loop.summary.slice(0, TRUNC.TOPIC_LABEL));
    const choice = await ctx.ui.select("Open loops", [...labels, "Done"]);
    if (!choice || choice === "Done")
      return changed ? overrides : null;
    const loop = loops[labels.indexOf(choice)];
    if (!loop)
      continue;
    const summaryKey = loop.summary.toLowerCase().replace(/\s+/g, " ").trim();
    const existing = overrides.find((item) => item.summaryKey === summaryKey);
    const action = await ctx.ui.select("Manage: " + loop.summary.slice(0, 60), [
      loop.status === "resolved" ? "Reopen" : "Resolve",
      existing?.pinned ? "Unpin" : "Pin",
      "Set priority",
      "Back"
    ]);
    if (!action || action === "Back")
      continue;
    if (action === "Resolve" || action === "Reopen") {
      overrides = upsertLoopOverride(overrides, loop, {
        status: action === "Resolve" ? "resolved" : "open"
      });
    } else if (action === "Pin" || action === "Unpin") {
      overrides = upsertLoopOverride(overrides, loop, {
        pinned: action === "Pin"
      });
    } else if (action === "Set priority") {
      const priority = await ctx.ui.select("Priority", [
        "critical",
        "high",
        "normal",
        "low"
      ]);
      if (!priority)
        continue;
      overrides = upsertLoopOverride(overrides, loop, {
        priority
      });
    }
    changed = true;
  }
}

// src/ui/overlays.ts
async function selectModel(ctx, opts) {
  const available = ctx.modelRegistry.getAvailable();
  const modeName = opts.mode ? MODE_LABELS[opts.mode] ?? opts.mode : undefined;
  const blocked = (model) => {
    const check = opts.feasibility?.(model, "summary", opts.mode);
    return check && !check.selectable ? check.reason ?? "not eligible" : undefined;
  };
  const options = available.map((m) => ({
    value: m.provider + "/" + m.id,
    label: m.provider + "/" + m.id,
    model: m,
    supportsTools: getProviderCaps(m.provider).supportsTools
  }));
  const items = options.map((o, i) => ({
    value: "model:" + i,
    label: o.label,
    description: blocked(o.model) ? "unavailable" : compactTokenCount(o.model.contextWindow) + " window" + (i === opts.defaultModelIndex ? " \xB7 selected" : "")
  }));
  const result = await ctx.ui.custom((tui, theme, _kb, done) => {
    const c = new Container2;
    c.addChild(new DynamicBorder2((s) => theme.fg("accent", s)));
    c.addChild(new Text2(theme.fg("accent", theme.bold("Choose summary model")), 1, 0));
    c.addChild(new Text2(theme.fg("dim", "Writes the compaction summary. Active context: " + opts.activeModelLabel + " (unchanged) \xB7 " + compactTokenCount(opts.contextTokens) + ", " + Math.round(opts.contextPercent) + "% full"), 1, 0));
    c.addChild(new Text2("", 0, 0));
    const sel = new SelectList2(items, Math.min(items.length, 10), {
      selectedPrefix: (t) => theme.fg("accent", t),
      selectedText: (t) => theme.fg("accent", t),
      description: (t) => theme.fg("muted", t),
      scrollInfo: (t) => theme.fg("dim", t),
      noMatch: (t) => theme.fg("warning", t)
    });
    const detail = new Text2("", 1, 0);
    const describe = (index, rejected = false) => {
      const option = options[index];
      if (!option)
        return detail.setText("");
      const reason = blocked(option.model);
      detail.setText(reason ? theme.fg("warning", (rejected ? "Choose another model. " : "") + "Can't use" + (modeName ? " for " + modeName : "") + ": " + reason) : theme.fg("dim", option.value + " \xB7 " + compactTokenCount(option.model.contextWindow) + " window" + (opts.feasibility && modeName ? " \xB7 fits the " + modeName + " plan" : "")));
    };
    const indexOf = (item) => parseInt(item.value.slice(6), 10);
    sel.setSelectedIndex(opts.defaultModelIndex);
    describe(opts.defaultModelIndex);
    sel.onSelectionChange = (item) => describe(indexOf(item));
    sel.onSelect = (item) => {
      const option = options[indexOf(item)];
      if (option && !blocked(option.model))
        return done(item.value);
      describe(indexOf(item), true);
      tui.requestRender();
    };
    sel.onCancel = () => done(null);
    c.addChild(sel);
    c.addChild(detail);
    c.addChild(new Text2("", 0, 0));
    c.addChild(new Text2(theme.fg("dim", "\u2191\u2193 choose \xB7 Enter use model \xB7 Esc back"), 1, 0));
    c.addChild(new DynamicBorder2((s) => theme.fg("accent", s)));
    return {
      render: (w) => c.render(w),
      invalidate: () => c.invalidate(),
      handleInput: (d) => {
        sel.handleInput(d);
        tui.requestRender();
      }
    };
  });
  if (!result?.startsWith("model:"))
    return null;
  return options[parseInt(result.slice(6), 10)] ?? null;
}
