async function showCompactUI(ctx, opts) {
  const available = ctx.modelRegistry.getAvailable();
  const asOption = (model) => ({
    value: model.provider + "/" + model.id,
    label: model.provider + "/" + model.id,
    model,
    supportsTools: getProviderCaps(model.provider).supportsTools
  });
  const capacity = (model, mode) => opts.feasibility?.(model, "summary", mode) ?? { selectable: true };
  const usable = (model) => PRIMARY_MODES.some((mode) => capacity(model, mode).selectable);
  let highlighted;
  const configured = available[opts.defaultModelIndex] ?? available[0];
  const initialModel = configured && usable(configured) ? configured : available.find(usable);
  if (!initialModel)
    return null;
  let selectedModel = asOption(initialModel);
  const calibration = createProductionServices().tokenCalibration;
  const damageMedian = preflightDamageMedian(ctx.cwd, opts.config);
  while (true) {
    const shared = prepareManualPreflightContext(ctx, selectedModel.model, calibration);
    const plans = new Map(PRIMARY_MODES.map((mode) => [
      mode,
      planManualPreflight(ctx, selectedModel.model, mode, calibration, opts.config, damageMedian, shared)
    ]));
    const recommended = recommendPreflight(plans);
    const engines = loadConfig().compactionEngines;
    const action = await ctx.ui.custom((tui, theme, keybindings, done) => {
      const fits = (mode) => capacity(selectedModel.model, mode).selectable;
      const preferred = highlighted ?? recommended.mode;
      let selected = Math.max(0, PRIMARY_MODES.indexOf(fits(preferred) ? preferred : PRIMARY_MODES.find(fits) ?? preferred));
      let details = false;
      let blockedEnter = false;
      let sectionOffset = 0;
      let sectionPage = 1;
      return {
        render: (width) => {
          const inner = Math.max(1, width - 2);
          const border = (text) => theme.fg("borderMuted", text);
          const cell = (text = "") => {
            const clipped = truncateToWidth2(text, inner, "");
            return border("\u2502") + clipped + " ".repeat(Math.max(0, inner - visibleWidth(clipped))) + border("\u2502");
          };
          const para = (text, color, indent = 2) => wrapTextWithAnsi(text, Math.max(1, inner - indent)).map((part) => cell(" ".repeat(indent) + theme.fg(color, part)));
          const divider = border("\u251C" + "\u2500".repeat(inner) + "\u2524");
          const title = truncateToWidth2(" Smart Compact ", Math.max(0, inner - 1), "");
          const top = border("\u256D\u2500") + theme.fg("accent", theme.bold(title)) + border("\u2500".repeat(Math.max(0, inner - 1 - visibleWidth(title))) + "\u256E");
          const bottom = border("\u2570" + "\u2500".repeat(inner) + "\u256F");
          const selectedMode = PRIMARY_MODES[selected];
          const modeName = MODE_LABELS[selectedMode];
          const current = plans.get(selectedMode);
          const check = capacity(selectedModel.model, selectedMode);
          const runnable = (current.plan?.viable ?? false) && check.selectable;
          const contextPct = Math.round(current.contextPercent);
          const barLength = inner >= 60 ? 14 : inner >= 40 ? 8 : 4;
          const barFilled = Math.min(barLength, Math.round(Math.min(100, contextPct) / 100 * barLength));
          const contextBar = theme.fg(contextPct >= 90 ? "error" : contextPct >= 70 ? "warning" : "success", "\u2588".repeat(barFilled)) + theme.fg("dim", "\u2591".repeat(barLength - barFilled));
          const modelText = "Summary model  " + selectedModel.label;
          const changeModel = "[M] Change";
          const modelFits = visibleWidth(modelText + changeModel) + 4 <= inner;
          const head = [
            top,
            cell("  Context  " + compactTokenCount(opts.contextTokens) + " / " + compactTokenCount(current.contextWindowTokens) + "  " + contextBar + " " + contextPct + "%"),
            ...modelFits ? [cell("  " + theme.fg("text", modelText) + "  " + theme.fg("accent", changeModel))] : para(modelText, "text"),
            divider
          ];
          const modeRows = PRIMARY_MODES.flatMap((mode, index) => {
            const plan = plans.get(mode).plan;
            const fitsModel = fits(mode);
            const viable = (plan?.viable ?? false) && fitsModel;
            const outcome = (mode === recommended.mode ? "recommended \xB7 " : "") + (viable && plan ? percent(plan.projectedYield * 100) + " saved" : fitsModel ? "unavailable" : "too large for model");
            const color = index === selected ? "accent" : !viable ? "muted" : mode === recommended.mode ? "success" : "text";
            const paint = (text) => index === selected ? theme.fg(color, theme.bold(text)) : theme.fg(color, text);
            const bare = " " + (index === selected ? "\u203A " : "  ") + MODE_LABELS[mode];
            for (const left of [bare.padEnd(13) + MODE_TRAITS[mode], bare]) {
              const gap = inner - visibleWidth(left) - visibleWidth(outcome) - 1;
              if (gap >= 2)
                return [cell(paint(left + " ".repeat(gap) + outcome))];
            }
            return [cell(paint(bare)), ...para(outcome, color, 5)];
          });
          const tradeoff = para(modeName + " (" + MODE_TRAITS[selectedMode] + "): " + MODE_TRADEOFFS[selectedMode], "muted");
          const essentials = [];
          if (!check.selectable)
            essentials.push(...para("Too large for this model: " + (check.reason ?? "the planned requests do not fit"), "warning"));
          if (blockedEnter)
            essentials.push(...para("Choose another mode or model.", "warning"));
          const brief = formatPreflightSummary(current, selectedModel.value, false, engines);
          const planLines = details ? formatPreflightSummary(current, selectedModel.value, true, engines) : brief;
          const summaryColor = (line) => line.startsWith("Unavailable") || line.startsWith("Plan unavailable") ? "warning" : line.startsWith("\u2713") ? "success" : "text";
          for (const line of brief)
            essentials.push(...para(line, summaryColor(line)));
          essentials.push(...para("Estimates, not guarantees.", "dim"));
          for (const line of planLines.slice(brief.length))
            essentials.push(...para(line, "dim"));
          if (details)
            essentials.push(...para("Recommendation: " + MODE_LABELS[recommended.mode] + " \u2014 " + recommended.reason, "dim"));
          const foot = [
            divider,
            ...para(runnable ? "Enter  Compact with " + modeName : "Enter  Compact \u2014 unavailable for " + modeName, runnable ? "accent" : "muted", 1),
            ...para("\u2191\u2193 mode \xB7 " + (modelFits ? "" : "M model \xB7 ") + "D " + (details ? "hide details" : "details") + (opts.showEffectiveState ? " \xB7 S state" : "") + " \xB7 Esc back", "dim", 1),
            bottom
          ];
          const rows = tui.terminal?.rows;
          const room = rows ? Math.floor(rows * 0.85) - head.length - modeRows.length - foot.length - 1 : Infinity;
          let section = tradeoff.length + essentials.length <= room ? [...tradeoff, ...essentials] : essentials;
          if (section.length > room) {
            sectionPage = Math.max(1, room - 1);
            sectionOffset = Math.max(0, Math.min(sectionOffset, section.length - sectionPage));
            const end = Math.min(section.length, sectionOffset + sectionPage);
            section = [
              ...section.slice(sectionOffset, end),
              cell("  " + theme.fg("dim", "\u2026 " + (sectionOffset + 1) + "\u2013" + end + " of " + section.length + " \xB7 PgUp/PgDn"))
            ];
          } else
            sectionOffset = 0;
          return [...head, ...modeRows, divider, ...section, ...foot];
        },
        invalidate: () => {},
        handleInput: (data) => {
          if (keybindings.matches(data, "tui.select.cancel")) {
            done(null);
            return;
          }
          if (keybindings.matches(data, "tui.select.up")) {
            selected = (selected + PRIMARY_MODES.length - 1) % PRIMARY_MODES.length;
            blockedEnter = false;
            sectionOffset = 0;
          } else if (keybindings.matches(data, "tui.select.down")) {
            selected = (selected + 1) % PRIMARY_MODES.length;
            blockedEnter = false;
            sectionOffset = 0;
          } else if (keybindings.matches(data, "tui.select.confirm")) {
            const mode = PRIMARY_MODES[selected];
            if (plans.get(mode).plan?.viable && fits(mode)) {
              done(mode);
              return;
            }
            blockedEnter = true;
            sectionOffset = 0;
          } else if (keybindings.matches(data, "tui.select.pageDown")) {
            sectionOffset += sectionPage;
          } else if (keybindings.matches(data, "tui.select.pageUp")) {
            sectionOffset = Math.max(0, sectionOffset - sectionPage);
          } else if (letterKey(data, "d")) {
            details = !details;
          } else if (letterKey(data, "m")) {
            highlighted = PRIMARY_MODES[selected];
            done("model");
            return;
          } else if (opts.showEffectiveState && letterKey(data, "s")) {
            done("state");
            return;
          }
          tui.requestRender();
        }
      };
    }, {
      overlay: true,
      overlayOptions: {
        width: "70%",
        minWidth: 56,
        anchor: "center",
        maxHeight: "85%"
      }
    });
    if (!action)
      return null;
    if (action === "state") {
      await opts.showEffectiveState?.();
      continue;
    }
    if (action === "model") {
      const modelIndex = available.findIndex((model) => model.provider === selectedModel.model.provider && model.id === selectedModel.model.id);
      const next = await selectModel(ctx, {
        ...opts,
        defaultModelIndex: Math.max(0, modelIndex),
        ...highlighted ? { mode: highlighted } : {}
      });
      if (next)
        selectedModel = next;
      continue;
    }
    return { model: selectedModel, mode: action };
  }
}

// src/app/steps/prepare.ts
async function prepareRun(rc) {
  const config = rc.config ?? loadConfig();
  const { profileCfg, estimator, adapted, damageMedian } = preparePreflightProfile({
    cwd: rc.ctx.cwd,
    summaryModel: rc.summaryModel,
    mode: rc.mode,
    tokenCalibration: rc.services.tokenCalibration,
    config
  });
  if (adapted) {
    rc.notify("Adaptive damage policy: median " + damageMedian + "/100 \u2014 preserving more recent context", "info");
  }
  const providerCaps = getProviderCaps(rc.summaryModel.provider);
  rc.services.thinkingLevels = {
    summaryThinkingLevel: config.summaryThinkingLevel,
    segmentationThinkingLevel: config.segmentationThinkingLevel
  };
  rc.services.codexWatchdogMs = config.codexMaxCallMs ?? DEFAULT_CONFIG.codexMaxCallMs;
  rc.services.scrubber = new SecretScrubber(config.scrubSecrets, config.scrubPii);
  if (config.maxLatencyMs > 0) {
    rc.timeoutMs = rc.timeoutMs > 0 ? Math.min(rc.timeoutMs, config.maxLatencyMs) : config.maxLatencyMs;
  }
  const policy = MODE_POLICIES[rc.mode];
  const callBudget = resolveCallBudget(config.maxLlmCalls, rc.mode, rc.maxLlmCalls, rc.flags.autoTriggered && !rc.flags.skipCompact);
  const inputBudget = effectiveBudget(config.maxLlmInputTokens, policy.maxInputTokens, rc.maxLlmInputTokens);
  rc.services.budget = new BudgetGuard(callBudget, rc.timeoutMs, rc.services.clock, inputBudget, policy.maxOutputTokens);
  if (rc.timeoutMs > 0) {
    rc.cancellation.timeoutId = setTimeout(() => {
      rc.cancellation.timedOut = true;
      rc.cancellation.controller.abort();
      rc.notify("Smart compact exceeded " + rc.timeoutMs + "ms; stopped without applying a Smart Compact summary. Review the latency budget or retry when ready.", "warning");
    }, rc.timeoutMs);
  }
  debug("prepareRun: profile=" + rc.profile + " model=" + rc.modelLabel);
  const out = rc;
  out.readerSignature = readerSignature(rc.ctx);
  out.config = config;
  out.profileCfg = profileCfg;
  out.providerCaps = providerCaps;
  out.estimator = estimator;
  out.adapted = adapted;
  return advance(out, "_prepared");
}

// src/app/steps/tier.ts
function selectTier(rc) {
  const toolPercent = computeToolCharPercentage(rc.msgs);
  const tier = rc.flags.overflowRecovery ? "full" : rc.flags.force ? rc.contextPercent >= 80 ? "full" : "light" : safeContextPercent(rc.totalTokens, effectiveContextWindow(rc.ctx.model, rc.config)) < rc.config.minContextPercent ? "none" : selectCompactionTier(rc.contextPercent, rc.totalTokens, MIN_TOKEN_THRESHOLD, 0);
  if (tier === "none") {
    if (!rc.flags.autoTriggered) {
      notifyUser(rc.ctx, "Context OK (" + Math.round(rc.contextPercent) + "%). Nothing to compact yet.", "info");
    }
    return null;
  }
  const out = rc;
  out.tier = tier;
  rc.toolPercent = toolPercent;
  return advance(out, "_tiered");
}

