// src/app/steps/visual.ts
async function attachVisualArchive(rc, render = renderVisualPages) {
  const model = rc.ctx.model;
  if (!rc.config.visualArchiveEnabled || !canReadVisual(model) || !model || rc.flags.overflowRecovery || rc.cancellation.signal.aborted)
    return;
  try {
    let sources = selectVisualSources(rc.branch, rc.toCompact, rc.finalSummary, rc.services.scrubber);
    let pages = visualPages(sources);
    const textTokens = rc.estimator.text(rc.finalSummary);
    const before = rc.details.estimatedAfterTokens ?? rc.totalTokens;
    const allowance = Math.min(rc.compactionPlan.targetAfterTokens - before, model.contextWindow - Math.max(8192, model.maxTokens ?? 0) - before) - 256;
    const estimate = () => pages.reduce((sum, lines) => {
      const size = visualPageSize(lines);
      return sum + estimateVisualTokens(size.width, size.height);
    }, 0);
    while (sources.length && estimate() > allowance) {
      sources = sources.slice(1);
      pages = visualPages(sources);
    }
    const reader = { provider: model.provider, id: model.id, api: model.api };
    const readerEstimator = makeTokenEstimator(model.provider, model.id, rc.services.tokenCalibration);
    if (!sources.length || !visualEconomics(reader, sources, pages.map(visualPageSize), readerEstimator.text).worthwhile)
      return;
    const frames = await render(pages, AbortSignal.any([rc.cancellation.signal, AbortSignal.timeout(5000)]));
    if (rc.cancellation.signal.aborted)
      return;
    const archive = {
      version: 1,
      reader,
      sources,
      frames,
      estimatedTokens: frames.reduce((sum, frame) => sum + estimateVisualTokens(frame.width, frame.height), 0)
    };
    if (!validVisualArchive(archive) || frames.length !== pages.length || !visualEconomics(reader, sources, frames, readerEstimator.text).worthwhile)
      return;
    const visualTokens = archive.estimatedTokens + 256;
    const yieldEstimate = verifyCompactionYield(rc.totalTokens, textTokens + visualTokens, rc.compactionPlan);
    rc.tokensSaved = yieldEstimate.estimatedSavedTokens;
    rc.details = {
      ...rc.details,
      ...yieldEstimate,
      summaryTokens: textTokens,
      tokensSaved: rc.tokensSaved,
      visualTokens,
      visualArchive: archive
    };
  } catch (error) {
    reportIssue({
      key: "visual.archive",
      message: "Visual archive unavailable (" + errorDetail(error) + "). The verified text compaction is used. Disable visualArchiveEnabled if this repeats.",
      error
    }, rc.ctx);
  }
}

