class InputSettingEditor extends Container3 {
  requestRender;
  save;
  done;
  input = new Input;
  status = new Text7("", 0, 0);
  saving = false;
  pending = Promise.resolve();
  get focused() {
    return this.input.focused;
  }
  set focused(value) {
    this.input.focused = value;
  }
  constructor(setting, initial, requestRender, save, done) {
    super();
    this.requestRender = requestRender;
    this.save = save;
    this.done = done;
    this.addChild(new Text7(setting.label, 0, 0));
    this.addChild(new Text7(setting.description, 0, 0));
    this.addChild(new Text7(`Allowed: ${setting.placeholder}`, 0, 0));
    this.addChild(new Text7("", 0, 0));
    this.input.setValue(initial);
    this.input.handleInput("\x1B[F");
    this.input.onSubmit = (value) => {
      if (this.saving)
        return;
      let parsed;
      try {
        parsed = setting.parse(value);
      } catch (error) {
        this.status.setText(error instanceof Error ? error.message : String(error));
        this.requestRender();
        return;
      }
      this.saving = true;
      this.status.setText("Saving\u2026");
      this.requestRender();
      this.pending = this.save(parsed).then(() => this.done()).catch((error) => {
        this.saving = false;
        this.status.setText(error instanceof Error ? error.message : String(error));
        this.requestRender();
      });
    };
    this.input.onEscape = () => {
      if (!this.saving)
        this.done();
    };
    this.addChild(this.input);
    this.addChild(new Text7("", 0, 0));
    this.addChild(this.status);
    this.addChild(new Text7("Enter save \xB7 Esc cancel", 0, 0));
  }
  handleInput(data) {
    this.input.handleInput(data);
    this.requestRender();
  }
  settled() {
    return this.pending;
  }
}

class ModelSettingEditor extends Container3 {
  requestRender;
  search = new Input;
  list;
  status = new Text7("", 0, 0);
  saving = false;
  pending = Promise.resolve();
  get focused() {
    return this.search.focused;
  }
  set focused(value) {
    this.search.focused = value;
  }
  constructor(models, selectedValue, requestRender, save, done) {
    super();
    this.requestRender = requestRender;
    this.addChild(new Text7("Type to search models", 0, 0));
    this.addChild(this.search);
    this.addChild(new Text7("", 0, 0));
    this.list = new SelectList3(models, 10, {
      selectedPrefix: (text) => text,
      selectedText: (text) => text,
      description: (text) => text,
      scrollInfo: (text) => text,
      noMatch: (text) => text
    });
    const selectedIndex = models.findIndex((item) => item.settingValue === selectedValue);
    this.list.setSelectedIndex(Math.max(0, selectedIndex));
    this.list.onSelect = (item) => {
      if (this.saving)
        return;
      this.saving = true;
      this.status.setText("Saving\u2026");
      this.requestRender();
      const selected = models.find((candidate) => candidate.value === item.value);
      if (!selected || selected.blocked) {
        this.saving = false;
        this.status.setText(selected?.blocked ? selected.label + " cannot be used: " + selected.blocked : "");
        this.requestRender();
        return;
      }
      this.pending = save(selected.settingValue).then(done).catch((error) => {
        this.saving = false;
        this.status.setText(error instanceof Error ? error.message : String(error));
        this.requestRender();
      });
    };
    this.list.onCancel = () => {
      if (!this.saving)
        done();
    };
    this.addChild(this.list);
    this.addChild(this.status);
    this.addChild(new Text7("Type to filter \xB7 Enter select \xB7 Esc cancel", 0, 0));
  }
  handleInput(data) {
    if (matchesKey3(data, Key3.up) || matchesKey3(data, Key3.down) || matchesKey3(data, Key3.enter) || matchesKey3(data, Key3.escape)) {
      this.list.handleInput(data);
    } else {
      this.search.handleInput(data);
      this.list.setFilter(this.search.getValue());
    }
    this.requestRender();
  }
  settled() {
    return this.pending;
  }
}
function inputLabel(setting) {
  return setting.label + (readGlobalConfigValue(setting.id) !== undefined ? CHANGED_MARK : "");
}
function inputDisplay(setting) {
  return setting.format(readGlobalConfigValue(setting.id));
}
function inputEffectiveDescription(setting, config) {
  return `${setting.description} Now: ${setting.format(effectiveValue(config, setting.id))}.`;
}
function inputSettingItem(setting, requestRender, writeConfig, onWritten = () => {}) {
  const item = {
    id: setting.id,
    label: inputLabel(setting),
    description: inputEffectiveDescription(setting, loadConfig()),
    currentValue: inputDisplay(setting)
  };
  item.submenu = (_current, close) => {
    const persisted = readGlobalConfigValue(setting.id);
    return new InputSettingEditor(setting, persisted === undefined ? "" : Array.isArray(persisted) ? persisted.join(", ") : String(persisted), requestRender, async (value) => {
      const effective = await writeConfig(setting.id, value);
      item.label = inputLabel(setting);
      item.currentValue = setting.format(value);
      item.description = inputEffectiveDescription(setting, effective);
      onWritten(effective);
    }, close);
  };
  return item;
}
function inputSettingsList(settings, requestRender, done, writeConfig, onError) {
  const items = settings.map((setting) => inputSettingItem(setting, requestRender, writeConfig));
  const byId = new Map(settings.map((setting) => [setting.id, setting]));
  return new SmartSettingsList(items, 9, () => {}, done, (id) => {
    const setting = byId.get(id);
    const item = items.find((candidate) => candidate.id === id);
    if (!setting || !item)
      return;
    writeConfig(setting.id, undefined).then((config) => {
      item.label = inputLabel(setting);
      item.currentValue = setting.format(undefined);
      item.description = inputEffectiveDescription(setting, config);
      requestRender();
    }, (error) => onError(error instanceof Error ? error.message : String(error)));
  });
}
function profileBudgetsList(requestRender, done, writeConfig, onError) {
  const modes = MODE_BUDGETS.map(({ mode, profile, label }) => {
    const ids = profileSettings(profile).map((setting) => setting.id);
    const item = {
      id: mode,
      label,
      description: `Token budgets used when a run is ${label}, including when Auto picks ${label}.`,
      currentValue: countChangedPaths(ids),
      submenu: (_current, close) => inputSettingsList(profileSettings(profile), requestRender, () => {
        item.currentValue = countChangedPaths(ids);
        close();
      }, writeConfig, onError)
    };
    return item;
  });
  return new SmartSettingsList(modes, 7, () => {}, done);
}
function countChangedPaths(ids) {
  const changed = ids.filter((id) => readGlobalConfigValue(id) !== undefined).length;
  return changed ? `${changed} changed` : "defaults";
}
function profileConfigPaths() {
  return PROFILE_NAMES.flatMap((profile) => profileSettings(profile).map((setting) => setting.id));
}
var STAGE_BY_SETTING = {
  summaryModel: "summary",
  segmentationModel: "segmentation",
  verificationModel: "verification"
};
function modelSettingsItems(ctx, requestRender, writeConfig = writeGlobalConfigValue, feasibility) {
  const config = loadConfig();
  return MODEL_SETTINGS.map((setting) => {
    const override = readGlobalConfigValue(setting.id);
    const current = typeof override === "string" ? override : "default";
    const fallback = setting.id === "summaryModel" ? "chat model" : "summary model";
    const describe = (effective) => `${setting.description} Now: ${effective[setting.id] ?? fallback}.`;
    const item = {
      id: setting.id,
      label: setting.label,
      description: describe(config),
      currentValue: current
    };
    item.submenu = (_value, close) => {
      const persisted = readGlobalConfigValue(setting.id);
      const selectedValue = typeof persisted === "string" ? persisted : "default";
      const effective = loadConfig();
      item.currentValue = selectedValue;
      item.description = describe(effective);
      const available = ctx.modelRegistry.getAvailable().map((model) => {
        const check = feasibility?.(model, STAGE_BY_SETTING[setting.id]);
        const blocked = check && !check.selectable ? check.reason ?? "not eligible" : undefined;
        return {
          value: `${model.provider}/${model.id} \u2014 ${model.name}`,
          settingValue: `${model.provider}/${model.id}`,
          label: `${model.provider}/${model.id}`,
          description: blocked ? "unavailable: " + blocked : model.name,
          ...blocked ? { blocked } : {}
        };
      }).sort((left, right) => left.value.localeCompare(right.value));
      const choices = [
        {
          value: `default \u2014 use the ${fallback}`,
          settingValue: "default",
          label: "default",
          description: `Use the ${fallback}`
        },
        ...available
      ];
      if (selectedValue !== "default" && !choices.some((candidate) => candidate.settingValue === selectedValue)) {
        choices.splice(1, 0, {
          value: selectedValue,
          settingValue: selectedValue,
          label: selectedValue,
          description: "Configured model is currently unavailable"
        });
      }
      return new ModelSettingEditor(choices, selectedValue, requestRender, async (selected) => {
        const effective = await writeConfig(setting.id, selected === "default" ? undefined : selected);
        item.currentValue = selected;
        item.description = describe(effective);
      }, close);
    };
    return item;
  });
}
function modelSettingItem(id, ctx, requestRender, writeConfig, feasibility) {
  return modelSettingsItems(ctx, requestRender, writeConfig, feasibility).find((item) => item.id === id);
}

