    reasons.push("compaction already running");
  const hostDriven = config.autoTriggerStrategy === "native-hook";
  lines.push("PSC auto: " + (policy.autoTrigger ? "on" : "off") + " \xB7 " + config.autoTriggerStrategy + (reasons.length ? " \u2014 " + reasons.join("; ") : hostDriven ? " \u2014 host-driven: acts only when Pi's own auto-compaction fires (threshold or overflow)" : " \u2014 PSC starts compaction when idle, subject to pressure and cooldown gates; Pi's auto-compaction setting is not needed"));
