// src/app/summary-anchor.ts
var ANCHOR_NAME_LIMIT = 120;
var ANCHOR_SUMMARY_LIMIT = 12000;
var SCRUB_RE = /[\x00-\x1f\x7f]/g;
function firstLine2(summary) {
  return summary.split(`
`).find((line) => line.trim()) ?? "Compaction summary";
}
function buildSummaryAnchor(sm, details) {
  const targetId = sm.getLeafId();
  if (!targetId)
    return null;
  const taken = new Set(sm.getEntries().flatMap((entry) => {
    const anchor = anchorFromEntry(entry);
    return anchor ? [anchor.name] : [];
  }));
  const base = ("compaction: " + firstLine2(details.summary)).replace(SCRUB_RE, " ").trim().slice(0, ANCHOR_NAME_LIMIT - 4);
  if (!base)
    return null;
  let name = base;
  for (let attempt = 2;taken.has(name) && attempt < 10; attempt++)
    name = `${base} \xB7 ${attempt}`;
  if (taken.has(name))
    return null;
  const summary = details.summary.slice(0, ANCHOR_SUMMARY_LIMIT);
  const anchor = { name, summary, targetId, synthetic: true };
  const content = `Anchor: ${name} (marks the compaction summary above; read it with smart_navigation view)`;
  return { customType: ANCHOR_CUSTOM_TYPE, content, display: false, details: { anchor } };
}

